private final Map<Project, Set<String>> mRegistered = new HashMap<>();
private final Map<Project, List<Candidate>> mCandidates = new HashMap<>();

private static class Candidate {
    final UClass cls;
    final JavaContext context;
    Candidate(UClass cls, JavaContext context) { ... }
}

@Override public void beforeCheckEachProject(@NonNull Context context) {
    Project project = context.getProject();
    mRegistered.put(project, new HashSet<>());
    mCandidates.put(project, new ArrayList<>());
}

@Override public void afterCheckEachProject(@NonNull Context context) {
    Project project = context.getProject();
    Set<String> registered = mRegistered.get(project);
    List<Candidate> candidates = mCandidates.get(project);
    if (registered == null || candidates == null) return;
    for (Candidate c : candidates) {
        String fqcn = c.cls.getQualifiedName();
        if (fqcn == null) continue;
        if (!registered.contains(fqcn)) {
            Location location = c.context.getNameLocation(c.cls);
            c.context.report(REGISTRATION_ISSUE, location, "Class is not registered in the manifest");
        }
    }
    // optional cleanup
    mRegistered.remove(project);
    mCandidates.remove(project);
}

